from dataclasses import dataclass
from typing import Callable, Iterable

from ci.kinds import KINDS


@dataclass(frozen=True)
class Artifact:
    key: str
    kind: str
    size: int
    age_days: int


@dataclass(frozen=True)
class Rule:
    kind: str
    action: str  # "delete" or "archive"
    max_age_days: int | None = None
    keep_last: int | None = None


def expire(rules: Iterable[Rule], items: list[Artifact], act: Callable[[str, Artifact], None]) -> None:
    for rule in rules:
        if rule.kind not in KINDS:
            raise ValueError(rule.kind)
        pool = sorted((a for a in items if a.kind == rule.kind), key=lambda a: a.age_days)
        for pos, artifact in enumerate(pool):
            too_old = rule.max_age_days is not None and artifact.age_days > rule.max_age_days
            too_many = rule.keep_last is not None and pos >= rule.keep_last
            if too_old or too_many:
                act(rule.action, artifact)

