// All calls come from the link task.
class Heartbeat {
  public:
    void on_receive();
    bool on_interval_end();  // true while the peer is offline

  private:
    static constexpr unsigned kMaxMisses = 3;
    unsigned misses_ = 0;
    bool seen_ = false;
    bool offline_ = false;
};

