def delay(attempt: int, base: float = 0.5, cap: float = 30.0) -> float:
    value = min(base, cap)
    for _ in range(attempt):
        value = min(value * 2, cap)
    return value


def spread(value: float, share: float) -> tuple[float, float]:
    return value * (1 - share), value * (1 + share)

